  protected override void DoAction(int action)
  {
#pragma warning disable 162, 1522
    switch (action)
    {
      case 2: // list -> stat
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 3: // stat -> select_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 4: // stat -> explain_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 5: // stat -> update_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 6: // stat -> delete_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 7: // stat -> insert_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 8: // stat -> create_table_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 9: // stat -> drop_table_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 10: // stat -> drop_database_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 11: // stat -> alter_table_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 12: // stat -> show_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 13: // stat -> create_index_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 14: // stat -> begin_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 15: // stat -> commit_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 16: // stat -> rollback_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 17: // stat -> set_transaction_stmt
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-1].n; }
        break;
      case 18: // opt_distinct -> TDISTINCT
{ CurrentSemanticValue.s = "1"; }
        break;
      case 19: // opt_distinct -> /* empty */
{ CurrentSemanticValue.s = null; }
        break;
      case 20: // select_stmt -> TSELECT, opt_distinct, select_field_list, TFROM, select_table, 
               //                opt_where, opt_group, opt_having, opt_order, opt_limit, 
               //                opt_offset
{ CurrentSemanticValue.n = new(NodeType.Select, ValueStack[ValueStack.Depth-9].n, ValueStack[ValueStack.Depth-7].n, ValueStack[ValueStack.Depth-6].n, ValueStack[ValueStack.Depth-3].n, ValueStack[ValueStack.Depth-2].n, ValueStack[ValueStack.Depth-1].n, ValueStack[ValueStack.Depth-5].n, ValueStack[ValueStack.Depth-10].s, ValueStack[ValueStack.Depth-4].n); }
        break;
      case 21: // explain_stmt -> TEXPLAIN, select_stmt
{ CurrentSemanticValue.n = new(NodeType.Explain, ValueStack[ValueStack.Depth-1].n, null, null, null, null, null, null, null); }
        break;
      case 22: // explain_stmt -> TEXPLAIN, LPAREN, TIDENTIFIER, RPAREN, select_stmt
{
               string opt = ValueStack[ValueStack.Depth-3].s.ToUpperInvariant();
               if (opt == "LOGICAL")
                   CurrentSemanticValue.n = new(NodeType.ExplainLogical, ValueStack[ValueStack.Depth-1].n, null, null, null, null, null, null, null);
               else if (opt == "PHYSICAL")
                   CurrentSemanticValue.n = new(NodeType.ExplainPhysical, ValueStack[ValueStack.Depth-1].n, null, null, null, null, null, null, null);
               else if (opt == "ANALYZE")
                   CurrentSemanticValue.n = new(NodeType.ExplainAnalyze, ValueStack[ValueStack.Depth-1].n, null, null, null, null, null, null, null);
               else
                   throw new CamusDB.Core.CamusDBException(
                       CamusDB.Core.CamusDBErrorCodes.InvalidInput,
                       "Unknown EXPLAIN option '" + ValueStack[ValueStack.Depth-3].s + "'. Valid options are: LOGICAL, PHYSICAL, ANALYZE.");
             }
        break;
      case 23: // opt_having -> THAVING, condition
{ CurrentSemanticValue.n = new(NodeType.Having, ValueStack[ValueStack.Depth-1].n, null, null, null, null, null, null, null); }
        break;
      case 24: // opt_having -> /* empty */
{ CurrentSemanticValue.n = null; }
        break;
      case 25: // query_expr -> LPAREN, select_stmt, RPAREN
{ CurrentSemanticValue.n = ValueStack[ValueStack.Depth-2].n; CurrentSemanticValue.s = ValueStack[ValueStack.Depth-2].s; }
